head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30699";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30699.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "img_11", attr: "src", fn: function () { return "/img/person/" + String((dma_pageContext.get("imgName1") ?? "")); } },
        { childId: "img_14", attr: "src", fn: function () { return "/img/person/" + String((dma_pageContext.get("imgName2") ?? "")); } },
        { childId: "img_17", attr: "src", fn: function () { return "/img/person/" + String((dma_pageContext.get("imgName3") ?? "")); } },
        { childId: "img_20", attr: "src", fn: function () { return "/img/person/" + String((dma_pageContext.get("imgName4") ?? "")); } },
        { childId: "img_23", attr: "src", fn: function () { return "/img/person/" + String((dma_pageContext.get("imgName5") ?? "")); } },
        { childId: "img_26", attr: "src", fn: function () { return "/img/person/" + String((dma_pageContext.get("imgName6") ?? "")); } },
        { childId: "img_29", attr: "src", fn: function () { return "/img/person/" + String((dma_pageContext.get("imgName7") ?? "")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name a_10_onmouseout
 * @description a_10 onmouseout 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.a_10_onmouseout = function(e){
    try {
        scwin.MM_swapImgRestore()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30699.a_10_onmouseout' }); }
};

/**
 * @method
 * @name a_10_onmouseover
 * @description a_10 onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.a_10_onmouseover = function(e){
    try {
        scwin.MM_swapImage('m01','','/img/person/person_menu_01_r.gif',1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30699.a_10_onmouseover' }); }
};

